CREATE DATABASE IF NOT EXISTS movie_streaming;
USE movie_streaming;
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE subscription_plans(plan_id INT AUTO_INCREMENT PRIMARY KEY,plan_name VARCHAR(50) NOT NULL UNIQUE,price DECIMAL(8,2) NOT NULL,duration_days INT NOT NULL,description VARCHAR(255));
CREATE TABLE payments(payment_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,plan_id INT NOT NULL,amount DECIMAL(8,2) NOT NULL,payment_status VARCHAR(20) DEFAULT 'SIMULATED',payment_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(plan_id) REFERENCES subscription_plans(plan_id));
CREATE TABLE genres(genre_id INT AUTO_INCREMENT PRIMARY KEY,genre_name VARCHAR(60) NOT NULL UNIQUE);
CREATE TABLE movies(movie_id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT,release_year INT,language VARCHAR(60),rating DECIMAL(3,1) DEFAULT 0,genre_id INT,FOREIGN KEY(genre_id) REFERENCES genres(genre_id));
CREATE TABLE series(series_id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT,release_year INT,language VARCHAR(60),rating DECIMAL(3,1) DEFAULT 0,genre_id INT,FOREIGN KEY(genre_id) REFERENCES genres(genre_id));
CREATE TABLE seasons(season_id INT AUTO_INCREMENT PRIMARY KEY,series_id INT NOT NULL,season_number INT NOT NULL,title VARCHAR(120),UNIQUE(series_id,season_number),FOREIGN KEY(series_id) REFERENCES series(series_id));
CREATE TABLE episodes(episode_id INT AUTO_INCREMENT PRIMARY KEY,season_id INT NOT NULL,episode_number INT NOT NULL,title VARCHAR(180) NOT NULL,duration_minutes INT,description TEXT,UNIQUE(season_id,episode_number),FOREIGN KEY(season_id) REFERENCES seasons(season_id));
CREATE TABLE actors(actor_id INT AUTO_INCREMENT PRIMARY KEY,actor_name VARCHAR(120) NOT NULL);
CREATE TABLE casting(casting_id INT AUTO_INCREMENT PRIMARY KEY,actor_id INT NOT NULL,movie_id INT NULL,episode_id INT NULL,role_name VARCHAR(100),CHECK((movie_id IS NOT NULL AND episode_id IS NULL) OR (movie_id IS NULL AND episode_id IS NOT NULL)),FOREIGN KEY(actor_id) REFERENCES actors(actor_id),FOREIGN KEY(movie_id) REFERENCES movies(movie_id),FOREIGN KEY(episode_id) REFERENCES episodes(episode_id));
CREATE TABLE reviews(review_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,movie_id INT NULL,series_id INT NULL,episode_id INT NULL,review_text TEXT NOT NULL,rating INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK((movie_id IS NOT NULL)+(series_id IS NOT NULL)+(episode_id IS NOT NULL)=1),CHECK(rating BETWEEN 1 AND 5),FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(movie_id) REFERENCES movies(movie_id),FOREIGN KEY(series_id) REFERENCES series(series_id),FOREIGN KEY(episode_id) REFERENCES episodes(episode_id));
CREATE TABLE watchlists(watchlist_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,movie_id INT NULL,series_id INT NULL,added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK((movie_id IS NOT NULL AND series_id IS NULL) OR (movie_id IS NULL AND series_id IS NOT NULL)),FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(movie_id) REFERENCES movies(movie_id),FOREIGN KEY(series_id) REFERENCES series(series_id));
